/* ============================================================
   THE PATTERN CATALOG. The clinical record, by seat.
   Seven plexus clusters, thirty-seven named categories, the
   count released at each and the count of coherent opposites
   installed. Ported from the earlier edition of the codex,
   where it is a summary: the source carries the counts and the
   nerve context, not the individual patterns, and this file
   does not invent what the source does not hold.
   ============================================================ */
const APC=[{"b":"Root","nv":"Coccygeal / Sacral Plexus (S4-Co1)","d":"Survival charge encodes in the coccygeal and sacral plexus because the body's primary question, am I safe?, routes through the lowest nerve roots. Scarcity, physical harm, and tribal rejection all converge here. Highest embodiment ratio in the system (27.7%). This layer is actively transitioning.","sub":[["Survival Fear",193,93],["Physical Body",114,2],["Financial Scarcity",82,0],["Tribal / Family",63,1],["Shelter / Stability",18,34]]},{"b":"Sacral","nv":"Sacral Plexus (S1-S3) / Hypogastric","d":"Creativity and desire encode in the sacral plexus because these are the body's generative functions at the nerve level. Suppressed creativity is a sacral nerve charge. The S1-S3 roots fire every time creative expression is blocked. Lowest embodiment ratio (2.6%). The creative suppression charge runs deeper than any other layer. The installation of coherent opposites has barely begun.","sub":[["Creativity Suppression",211,7],["Emotional Flow",197,5],["Pleasure / Guilt",135,1],["Sexual Identity",64,1],["Relationships / Intimacy",13,2]]},{"b":"Solar","nv":"Solar / Celiac Plexus (T5-T12)","d":"The celiac plexus is the most complex autonomic network outside the brain. Power, self-worth, shame, and will all encode here because this is where the body processes its relationship to the external world. The felt sense of \"can I handle this?\" is a celiac plexus response. 31.9% of total pattern load. Every major saboteur structure in the catalog has a Solar Plexus root node.","sub":[["Self-Worth / Inadequacy",366,56],["Willpower / Giving Up",330,1],["Power / Powerlessness",124,16],["Control / Chaos",118,6],["Anger / Rage",111,1],["Shame / Humiliation",92,1],["Responsibility Avoidance",68,5]]},{"b":"Heart","nv":"Cardiac Plexus / Vagus (T1-T4)","d":"The cardiac plexus receives vagal branches carrying relational information upward from the gut. Grief, love, abandonment, and forgiveness encode here because the heart conducts the information of relational experience through its nerve branches. 14.6% embodiment, the highest rate among the major clusters. When heart patterns clear, coherent opposites install effectively.","sub":[["Love / Fear of Love",122,11],["Forgiveness",84,7],["Connection / Isolation",25,16],["Abandonment / Rejection",23,2],["Grief / Loss",14,3]]},{"b":"Throat","nv":"Pharyngeal / Cervical Plexus (C1-C4)","d":"The cervical plexus innervates the structures of vocalization. Voice suppression is a cervical nerve charge, a literal nerve-level tightening around the mechanisms of speech every time the person was silenced, shamed for speaking, or punished for having a voice. 405 of 604 Throat patterns are Voice Suppression alone. The charge is not about confidence as a concept. It is about C1-C4 nerve roots firing at the moment of self-expression.","sub":[["Voice Suppression",405,5],["Self-Expression Blocks",38,26],["Public Speaking / Visibility",32,6],["Judgement Fear",17,0]]},{"b":"3rd Eye","nv":"Optic / Trigeminal / Cranial Nerves (CN II, V)","d":"The trigeminal nerve is the largest cranial nerve, with connections into the optic pathways. Decision paralysis and unclear direction are not thinking problems. They are trigeminal and optic nerve charges that fire when the person is about to commit to a direction. Vision/Direction carries 123 patterns, the dominant subcategory. The charge that keeps a person from seeing their next step has a specific cranial nerve address.","sub":[["Vision / Direction",123,9],["Perception / Reality",69,1],["Decision Paralysis",23,6],["Intuition Denial",17,2],["Overthinking / Mental Loops",9,0]]},{"b":"Crown","nv":"Pineal / Reticular Formation / Cranial Convergence","d":"\"I AM\" constructions encode at the crown because this is the convergence point of all cranial nerve inputs. Every belief about self, every self-limiting story, routes through the pineal and reticular formation. The crown is not a spiritual location. It is a nerve topology. 196 Identity/I Am patterns. Each one is a self-limiting I AM construction running as a retrieval command at the nerve level.","sub":[["Identity / I Am",196,17],["Existential Despair",106,9],["God / Source",56,1],["Surrender / Trust",14,4],["Purpose / Mission",14,0],["Ascension / Awakening",2,1]]}];
const APC_REL=3688, APC_EMB=358;

/* ============================================================
   THE KNOWLEDGE BASE. Definition, trigger and interrupt for the
   thirty three saboteurs, the nineteen domains read clear and
   read distorted, the glossary, and the index of the seventy six
   harmonic elements. Ported from the codex.

   Keys are the name with a leading "the" stripped and lower
   cased, because the book prints The Negotiator and the engine
   prints Negotiator. All thirty three join. Fifteen of the
   nineteen domains join; the four that do not are the ones the
   book renamed, and KB_RENAME records both names rather than
   picking one, because that ruling is the owner's.
   ============================================================ */
var KB_KEY=function(s){return String(s||'').replace(/^[Tt]he\s+/,'').toLowerCase().replace(/-/g,' ');};
var SABDEF={"negotiator":{"c":"S01","d":"Argues against your own intentions. Always sounds reasonable. Never says stop forever, says stop today. The fear of discomfort is mild enough to be rationalized away. The happiness available from the easier option is just high enough to make the rationalization feel earned. Together they produce the internal diplomat who can talk you out of anything, not through force, but through the perfectly reasonable argument that now is not the right moment. The most dangerous saboteur in the system because it sounds exactly like you.","t":"The moment between intending to do the necessary thing and beginning to do it. The pause.","i":"Begin the action before the internal dialogue completes. Remove the pause. The Negotiator only has power in the gap between intention and motion. Close the gap.","q":"I can start tomorrow. / Just this once. / I've earned a break."},"controller":{"c":"S02","d":"Hypervigilance at the level of outcomes. The foundation of the Type A pattern. Not a personality trait, a fear response that has been running so long it looks like a management style. The fear underneath: something will go wrong, someone will get hurt, or the situation will fall apart if I release my grip. Self-control registers as 10. Anything less registers as loss. The delta between perceived control and actual control is the zone of active saboteur behavior. Anger layers in as a do-as-I-say mechanism, authority used to close the control gap quickly. Entitlement provides the justification: it is not just that I need to control this. It is that I am right to. Competition drives the adversarial edge, not just winning but not-losing, which is a different frequency entirely.","t":"The moment control begins to slip. Uncertainty in outcomes. Others not performing to expectation. Delegation without confirmation. Silence where confirmation should be.","i":"Control is not a state. It is a belief held under pressure. The person fails control the same way a person fails a landing, only if they quit. Recognize that the need to be in control and the experience of being out of control are both charges, not conditions. Neither is real. Locate the fear underneath. Release the fear. The control behavior loses its substrate.","q":"If I don't control this, something will go wrong."},"victim":{"c":"S03","d":"Focuses on internal feelings and victim mentality for attention. Martyrdom.","t":"When accountability is required.","i":"Identify one thing within your control. Take one action on it.","q":"This keeps happening to me."},"perfectionist":{"c":"S04","d":"Continuous pressure to do better. Anxiety about imperfections in self and others.","t":"Before completion or release of work.","i":"Set a fixed completion time. Release at that time regardless of state.","q":"It is not good enough yet."},"pleaser":{"c":"S05","d":"Indirectly tries to gain acceptance by helping, pleasing, rescuing, or flattering.","t":"When there is potential for disapproval or when a boundary is needed.","i":"State a preference or limit once. Do not explain or apologize.","q":"My worth depends on making others happy."},"hyper achiever":{"c":"S06","d":"Dependent on constant performance for self-respect. Workaholic.","t":"When performance is not being measured or when rest is available.","i":"Rest without producing for one hour. No metrics.","q":"My worth is in my output."},"hyper rational":{"c":"S07","d":"Processes everything through logic. Impatient with emotional concerns.","t":"When emotional input is offered.","i":"Name the emotion present in the room before analyzing the problem.","q":"If I can't explain it, it isn't real."},"hyper vigilant":{"c":"S08","d":"Continuous anxiety about potential dangers. Constant risk management.","t":"When the environment changes or trust is required.","i":"Identify one thing that is safe. Hold that for 60 seconds.","q":"The threat is always just ahead."},"restless":{"c":"S09","d":"Constant search for new activities. Rarely at peace with the current moment.","t":"When the current situation becomes familiar or stable.","i":"Stay with the current thing for twice as long as the impulse to move suggests.","q":"The next thing will be better."},"stickler":{"c":"S10","d":"Perfectionism and need for order. Anxiety when standards are not met.","t":"When the environment or person deviates from the correct way.","i":"Identify one situation where your standard is serving your fear, not your values.","q":"There is a right way and a wrong way."},"judge":{"c":"S11","d":"Judges self and others. Replays past failures. The master saboteur, activates all others.","t":"When someone, including self, falls short of standard.","i":"Find one thing that is right about the situation being judged.","q":"Someone is responsible for this."},"deflector":{"c":"S12","d":"Does not own. Justification to avoid accountability.","t":"When direct accountability or personal disclosure is required.","i":"Stay with the direct question for 10 seconds before redirecting.","q":"If they knew the real me they would leave."},"dramatizer":{"c":"S13","d":"Amplifies the emotional intensity of situations to generate attention or movement.","t":"When intensity of feeling is present and an audience is available.","i":"Reduce the intensity of the next statement by half.","q":"My pain must be visible to matter."},"worrywart":{"c":"S14","d":"Runs continuous worst-case scenarios. Mistakes anxiety for planning.","t":"When the future is uncertain.","i":"Name the specific worst case. Name one action if it occurs.","q":"Worrying is preparation."},"loner":{"c":"S15","d":"Withdraws from contact as protection. Independence as defense, not a value. Fear of rejection co-mingling with shame of belonging at sufficient magnitude. The person does not experience themselves as afraid, they experience themselves as preferring solitude. Release the fear and sad nodes and the solitude remains if chosen, not if driven.","t":"When connection is available and would be beneficial.","i":"Make one direct request for connection.","q":"Needing others is weakness."},"people pleaser":{"c":"S16","d":"Approval-seeking at the expense of authenticity.","t":"When approval is uncertain or a boundary is needed.","i":"Identify the response that serves the relationship rather than the approval.","q":"If they don't like me I have failed."},"skeptic":{"c":"S17","d":"Defaults to distrust and doubt. Skepticism as protection against disappointment.","t":"When new information challenges the current model.","i":"Sit with the new information for 24 hours before dismissing it.","q":"Trust gets you hurt."},"dreamer":{"c":"S18","d":"Lives in possibility without building the bridge toward it. Avoids the friction of execution.","t":"When the gap between vision and current reality is visible.","i":"Identify one concrete step. Execute it today.","q":"Someday the conditions will be right."},"procrastinator":{"c":"S19","d":"Delays action on important tasks. Mistakes motion for progress.","t":"When the important task is clear and available.","i":"Begin. Not finish. Not plan. Begin. Three minutes.","q":"I work better under pressure."},"imposter":{"c":"S20","d":"Believes their competence is unearned and discoverable as fraud.","t":"When competence is being evaluated or recognition is offered.","i":"Identify one thing you know that the room does not. State it.","q":"They will find out I do not belong here."},"aggressor":{"c":"S21","d":"Uses anger and force to override resistance. Mistakes compliance for agreement.","t":"When authority is challenged or outcome is not proceeding as required.","i":"Pause 5 seconds. Name the fear underneath the anger before responding.","q":"Aggression gets results."},"martyr":{"c":"S22","d":"Sacrifices for others to generate obligation or moral authority.","t":"When sacrifice has been made and goes unrecognized.","i":"Identify whether the sacrifice was chosen or performed. If performed, stop.","q":"I give everything and receive nothing."},"cynic":{"c":"S23","d":"Undermines possibility through pre-emptive dismissal.","t":"When hope or enthusiasm is present in self or others.","i":"Identify one thing good about the situation being dismissed.","q":"Optimism is naive."},"manipulator":{"c":"S24","d":"Achieves outcomes indirectly through influence, withholding, or positioning.","t":"When the direct approach feels risky.","i":"State the actual need directly. Once. Without positioning.","q":"Direct requests make me vulnerable."},"overthinker":{"c":"S25","d":"Loops on decisions past the point of useful analysis.","t":"When a decision is required and the outcome is uncertain.","i":"Set a decision time limit. Decide at that limit. Do not extend it.","q":"More analysis will produce the right answer."},"escapist":{"c":"S26","d":"Uses pleasure, distraction, or movement to exit discomfort before it resolves.","t":"When the present moment is uncomfortable and an exit is available.","i":"Stay in the discomfort for two minutes. Name what is present.","q":"I just need to not feel this right now."},"avoider":{"c":"S33","d":"Declines the engagement before it can cost anything. Not fleeing discomfort the way the Escapist does, and not arguing the way the Negotiator does. Simply not present for it.","t":"When something asks to be dealt with and not dealing with it carries no immediate penalty.","i":"Name the thing being avoided out loud, then do the smallest piece of it.","q":"If I stay unaware, nothing can land on me."},"nihilist":{"c":"S27","d":"Removes the foundation of meaning as a pre-emptive strike against disappointment.","t":"When meaning is required to justify effort.","i":"Identify one action worth doing regardless of meaning. Do it.","q":"Nothing matters enough to sustain effort."},"innocent":{"c":"S28","d":"Maintains deliberate unawareness to avoid responsibility or conflict.","t":"When complexity, conflict, or moral weight is present.","i":"Name one thing you know that you are pretending not to know.","q":"I don't want to be involved."},"pessimist":{"c":"S29","d":"Pre-empts positive outcomes by building a case against them before they materialize.","t":"When a positive outcome is possible.","i":"Identify the best plausible case. Operate from that.","q":"It will not work out."},"catastrophizer":{"c":"S30","d":"Projects the worst possible outcome onto every uncertainty. Distinguishable from Worrywart by magnitude, Catastrophizer reaches existential threat from ordinary uncertainty.","t":"Any unresolved uncertainty.","i":"Describe the actual current situation without projection. Stay in the present tense.","q":"This will destroy everything."},"enabler":{"c":"S31","d":"Supports others' destructive patterns to maintain relationship or avoid conflict. Distinct from Pleaser: the Enabler supports behavior they recognize as harmful.","t":"When someone they care about is repeating a destructive pattern.","i":"Name what you see. Once. Without attachment to the response.","q":"If I say something they will leave."},"control freak":{"c":"S32","d":"The colloquial name for the Controller and Hyper-Vigilant composite at Type A intensity. Hypervigilance running on outcomes and on threat at the same time. The body is scanning forward (what could go wrong) and downward (am I in command of this) in continuous loop. Reads to other people as competence under pressure. Reads in the body as never landing. The same fear that drives Controller (something will go wrong if I release grip) and the same fear that drives Hyper-Vigilant (the threat is just ahead) co-mingle here at sufficient magnitude that they cannot be felt as separate. Distinct from Controller alone: Control Freak does not wait for the control gap to open before acting. Distinct from Hyper-Vigilant alone: Control Freak organizes the scan around its own agency, not around external monitoring. Type A is the social presentation. The somatic state is sustained sympathetic activation that the body has normalized as baseline.","t":"Any environment the person did not configure. Any outcome the person did not design. Any silence where confirmation should be.","i":"Lock the jaw, the shoulders, and the diaphragm for a count of five. Notice they were already locked. Release on the exhale. The release is not a relaxation technique, it is a demonstration that the body can hold a state without scanning it. Repeat until the scan stops without being asked to.","q":"If I am not running this, no one is."}};
var DOMDEF={"knowledge":{"n":"I","c":"pattern recognition, codification, teaching, symbolic thinking. The person who reads before being asked to. Somatic knowledge is true knowledge, once it's in the body, deception doesn't work on you. You can feel the lie before it forms a word.","x":"over-intellectualization, false certainty, knowledge as a barrier rather than a bridge."},"communication":{"n":"II","c":"bridging, translation, precision of language, fast cognition. The connector, the person who translates between people, between ideas, between worlds.","x":"manipulation, inconsistency, information as leverage."},"power":{"n":"III","c":"physical courage, boundary enforcement, protection of what matters. Directed aggression at obstacles, not people.","x":"domination, violence without purpose, war as identity."},"imperium":{"n":"IV","c":"governance, structural authority, organizing chaos into function. sees how systems should be organized.","x":"domination, entitlement, autocracy."},"creation":{"n":"V","c":"building, executing, bringing vision into form. Always needed to make things. When you can't create it feels like disconnection, like the system is broken. Financial stress kills creativity not motivationally but anatomically: the survival charge consumes the current before it reaches the generative center. When the root clears, the sacral opens, the creative current flows again. Not as discipline. As a natural consequence of the channel being clear.","x":"perfectionism as paralysis, identity tied to output."},"dissolution":{"n":"VI","c":"deliberate dissolution, clearing what's false or finished, making space for what comes next. Sees what needs to end.","x":"destruction as identity, nihilism, chaos without rebuilding."},"love":{"n":"VII","c":"union, intimacy, the force that draws beings into genuine contact. Love as a state the person generates, not receives. Always knew what brings people together.","x":"codependency, possession, love as completion rather than addition."},"healing":{"n":"VIII","c":"directed intervention, active clearing, creating conditions in which restoration happens. Finds the broken thing in any room.","x":"rescuer complex, martyrdom, healing as identity."},"sacrifice":{"n":"IX","c":"voluntary descent, the chosen ordeal, sacrifice as the mechanism that produces insight unavailable any other way. The knowledge that comes from what was given up, not accumulated. The true utilization of experience: consume as much as possible, then don't hang onto the definitions. Words illuminate, they don't contain.","x":"suffering as identity, the descent without return."},"justice":{"n":"X","c":"discernment of what's real and what's false. Accountability without cruelty. Moral disorder doesn't just feel wrong, it triggers the nervous system. When truth is a 10, anything less is somatic. You can feel the lie before it forms a word. If you lie, you dysregulate your own nervous system.","x":"rigid judgment, self-righteousness, justice as control."},"trickster":{"n":"XI","c":"disruption of rigid patterns, revealing what's hidden through inversion, innovation through disorder. Sees the absurdity in what everyone else treats as fixed.","x":"deception as lifestyle, instability mistaken for freedom."},"nature":{"n":"XII","c":"alignment with biological truth, growth through patience rather than force. Thinks in cycles rather than straight lines.","x":"rejection of structure, naturalism as escape from complexity."},"mystery":{"n":"XIII","c":"navigation of the unseen, death and rebirth as structural realities. Can hold darkness without being consumed. Always drawn to what's hidden.","x":"obsession with shadow, nihilism, identity built on the margin."},"duty":{"n":"XIV","c":"right action regardless of personal cost. Loyalty to what's true, not what's comfortable. Does the right thing even when no one is watching.","x":"rigidity, losing self in obligation, duty performed for an audience."},"play":{"n":"XV","c":"the generative state of pure engagement. Awe. Creativity for its own sake. Not the absence of seriousness, the intelligence serious people miss. Always able to find what's alive in something.","x":"avoidance through play, irresponsibility, lightness that refuses depth."},"death":{"n":"XVI","c":"completion. Endings held cleanly. The threshold kept, the thread cut when the thread is finished, presence with what's dying without flinching. Releases what's done so renewal has room.","x":"morbidity, clinging that refuses every ending, or dealing endings as power."},"fate":{"n":"XVII","c":"reads the pattern and its timing. Knows what must unfold and when to move. Acts at the right moment without forcing the thread.","x":"fatalism, abdication of choice, reading the pattern as an excuse to never act."},"guardian":{"n":"XVIII","c":"the watch kept. A perimeter held so what's inside can live. Protection without possession, sanctuary without walls that strangle.","x":"overprotection that smothers, vigilance that never rests, walls against life itself."},"provision":{"n":"XIX","c":"the one who makes sure there's enough, and not only for today. Supply held against a season nobody can see yet. The granary, the harvest, the wage. Provides for, rather than trades with.","x":"worth measured only in what's furnished, hoarding dressed as prudence, the provider who can't be provided for."}};
var KB_RENAME={"descent":"Sacrifice","connection":"Love","exchange":"Communication","restoration":"Healing"};
var GLOSS=[{"t":"Address","d":"The specific location in the body’s energetic architecture where a pattern is resident. Every fetter, every tag, every limiting belief has an address. The release work operates at the address--not at the level of thought or behavior."},{"t":"Allostatic load","d":"The accumulated physiological cost of chronic stress responses. The body’s equivalent of compound interest on unresolved charge. The release work reduces allostatic load by addressing it at the address layer."},{"t":"Archetype","d":"One of 12 universal character templates, and the third rung on the native side of the stack. Domains express as the blueprint; the blueprint branches into archetypes. A separate rung from the blueprint rather than another name for it. Native and present before conditioning, which is why it isn't held in tissue and not released: the work changes where it's pointed, not what it is."},{"t":"Ascension","d":"No longer affected, triggered, or stimulated by the external environment, or by your own emotions. You've ascended emotions controlling you. The environment loses its grip because survival patterns are no longer running as commands. A state definition, not a threshold: it carries no release count. It's not a destination--an operating state."},{"t":"Attention","d":"The ability to focus awareness. Two types: nonfocused attention and focused attention. Attention is the steering; will is the force."},{"t":"Aura","d":"The biophoton field generated by the state of the nervous system. Measurable. Determines social magnetism or repulsion. Reflects the charge load in the underlying nodes."},{"t":"Awareness","d":"The aperture of perception of the soul."},{"t":"Biophoton field","d":"The measurable light field generated by the state of the nervous system. The physical substrate of the aura. Its quality reflects the charge load in the underlying nodes and determines how the practitioner is received in social space."},{"t":"Chakra","d":"The nonphysical field generated by a nerve plexus. It's not a metaphor--a field with measurable properties. Seven primary chakras, each generated by its corresponding nerve plexus."},{"t":"Charge","d":"Stored survival energy held at a node. Installed by a stress response that never finished. Felt as heat, pressure, tingling, or weight when accessed."},{"t":"Clair","d":"A perceptual channel beyond the five physical senses. Clairvoyance (seeing), clairaudience (hearing), clairsentience (feeling), claircognizance (knowing), and others. Soma fields fragment them; clearing soma allows them to operate in unison."},{"t":"Coherence","d":"Measurable reduction of internal contradiction. The state in which intention, behavior, and nervous system response are aligned. CQ measures it."},{"t":"Replacement state","d":"The specific behavioral, emotional, and somatic expression of the quality a pattern suppresses--installed at the same address as the released charge. Not a generic positive. The exact quality the pattern is blocking."},{"t":"Consciousness","d":"Energy as information, perceived through two experiences. The macro is unbound and unfocused: infinite consciousness. The opposite pole is localized conscious awareness. Same thing, different aperture."},{"t":"CQ","d":"Coherence Quotient. (Intention × Integrity) ÷ Resistance. Baseline: 100. Measures the degree to which the system operates without internal contradiction."},{"t":"Distortion","d":"Intention read through loaded nodes. The signal is intact, the instrument is bent. Not a formula variable: distortion and SQ were the same reading under two names. It survives as a description of what happens to intention, not as a term that gets multiplied by anything."},{"t":"DQ","d":"Decoherence. DQ = 100 − CQ. Derived, not measured. There's no separate instrument for it, and any build that reports one is reporting arithmetic as though it were a reading. A high DQ means the system is consuming energy maintaining internal contradictions."},{"t":"Drag","d":"The combined load that reduces available willpower. Fetters, clenched muscles, inflammation, loaded nodes--all produce drag on the mind-body-spirit connection. Drag is why willpower feels like a limited resource."},{"t":"Earth Star","d":"Field node at the center point between the feet. Anchors the system to the planet."},{"t":"Ego","d":"Body consciousness. The mind attached to the physical, never present, toggling between thinking and feeling to navigate the world out of fear. The ego is the mask of our character. It's the total sum of DQ, all the SQ running, and all the patterns and awareness that come with body consciousness."},{"t":"Fetter","d":"A named conditional response pattern resident at a specific node address. 108 fetters in the body, one per physical node. 112 total addresses include 4 field nodes just outside the body, two above the crown, two below the feet. Fires when matching input arrives, regardless of how long ago it was installed."},{"t":"Five paths","d":"Five primary orientations toward the work: Krishna (flow), Buddha (awareness), Christ (somatics), Rama (alignment), Lao Tzu (horizontal). All paths lead to the same Source. The Anchor Principle operates underneath all five."},{"t":"Hardened mask","d":"The layer of conditioning that doesn't clear with time, life change, or most therapeutic modalities. Requires active address-level release work. Distinguished from practice-maintained conditioning, which life change alone can clear."},{"t":"Hyper-complex","d":"One of 8 named clusters of saboteurs operating as a unified behavioral system. More severe than a single saboteur--a self-reinforcing architecture of patterns that maintain each other."},{"t":"Integrity","d":"The total sum of your coherence, which upregulates the nervous system. It does that by moving you through and maintaining moral structure. Integrity is a ship’s hull. A hole in the hull means the ship takes on water. Integrity has to be at a hundred percent for the hull, and for CQ, to hold. Measured as compliance with the 21 Laws of Moral Integrity."},{"t":"Intention","d":"The intended outcome. Part willpower, part desire, part motivation. Moving toward something registers as pleasure. If no outcome has been formed, avoidance takes the slot by default."},{"t":"Justification mechanic","d":"The body’s defense of its own installed patterns. Blame, deflection, rationalization--all are the tag’s immune response. The body defends the signal because the truth is too difficult to face. Narcissism is the justification mechanic at high intensity."},{"t":"Karma","d":"The results of your thoughts and physical actions put out into the world, and the cause-and-effect energy that comes back to you from those actions. It's cyclical, an echo. Its purpose is to come back so you can learn the lesson, overcome, and transmit the karma so it never comes back. Karma is cause and effect in interaction."},{"t":"Kosha","d":"A perceptual layer through which experience is filtered. Six layers: physical, energetic, mental, wisdom, bliss, and linguistic. Each transforms the signal passing through it."},{"t":"Kundalini","d":"The stored vital energy at the base of the spine. Rises root to crown when enough nodes are cleared for the channel to conduct."},{"t":"Letting go","d":"The release protocol. Runs two mechanics in sequence: (1) reducing charge at the address, (2) installing the replacement state while the address is open. Different from affirmation, which skips the first mechanic."},{"t":"Limiting belief","d":"A tag that compresses the full range of experience into a limited label. Every identification is a limiting belief by definition--not as a judgment but as a mechanism. The label is always smaller than the experience."},{"t":"Mask","d":"The accumulated distortion functioning as an identity construct. What most people call ‘their personality’--the conditioned firing of patterns stored at specific addresses. The mask isn't who you are."},{"t":"Memory","d":"The result of the vritti and identification. Sensory input and emotional input, once identified, stored in the body."},{"t":"Merkaba","d":"A geometric field structure used in the release protocol. Top spinning left, bottom spinning right. Opposing rotations distort the node’s current flow, creating conditions for release."},{"t":"Node","d":"An address in the body’s energetic architecture. 108 physical nodes in the body. 4 field nodes just outside it: the Earth Star at the center point between the feet, the Sol Star just above the crown, and the Gaia Gateway below the Earth Star, and the Stellar Gateway above the Sol Star. 112 total."},{"t":"OJAS","d":"Sanskrit, meaning vigour. It isn't an acronym and there are no letters to expand; every instance spelled OJOS in earlier drafts was a transcription error that propagated. Vital energy in meditation, held as a cocoon of energy around you. It spins without you having to drive it, and it naturally stimulates the nervous system and releases stress from the body. The protocol developed for Stage 4 and Stage 5 nodes, the ones too dense or too numb to feel. Restores enough signal for release work to begin."},{"t":"Perception","d":"The ability to intuit and perceive, and to translate energy into a symbolic form that can be perceived and understood. Perceiving the sensory input to make sense of things."},{"t":"Plexus","d":"A physical nerve cluster. The plexus is the hardware; the chakra is the field it generates. Disruption at the plexus level produces disruption at the chakra level."},{"t":"Presence","d":"The ability to project one’s energy to be perceived and felt by others."},{"t":"Primary node","d":"The primary loaded node in a field of surrounding nodes. Clear the primary node and the surrounding field releases on its own. Working secondary nodes without finding the primary node produces partial release."},{"t":"Pure perception","d":"All the clairs operating in unison without distortion. Not an absence of thought--a state of full multi-sensory field coherence. Available as soma load reduces and the barriers between the clairs dissolve."},{"t":"Reading-as-release","d":"The protocol in which reading a properly constructed Letting Go sequence produces somatic release at the anatomical address the sequence specifies. No additional visualization required. Both mechanics run through the act of reading."},{"t":"Release","d":"The discharge of stored charge through the nervous system. Physical and observable: heat, shaking, tears, breath shifts. The pattern loses its power source."},{"t":"Resistance","d":"The denominator in the CQ formula. All drag combined--every fetter, loaded node, and inflammatory process that opposes the flow of signal through the system. Resistance is what the release work reduces."},{"t":"Saboteur","d":"One of 33 named behavioral patterns that contract a fetter into characteristic repeating behavior. Each has a specific belief structure, body location, and emotional signature."},{"t":"Self-unraveling state","d":"The body’s autonomous release state when enough gates have cleared. The soma fields begin releasing without active protocol work. The operational success criterion of a release session: not the node is cleared, the body is releasing on its own."},{"t":"Signal chain","d":"The full processing loop: field of awareness → senses → nervous system → brain → intelligence layer → relation layer → three axes → emotional layer → superego → koshas → archetypes → main field. The loop completes moment to moment."},{"t":"Soma","d":"The energetic field generated by the nervous system’s state. Accumulated soma creates load. Overlapping soma fields fragment the perceptive layer, forming barriers the awareness can't see through."},{"t":"Sol Star","d":"Field node just above the crown. The point through which the system extends beyond the body and opens to the field."},{"t":"Source","d":"The ground state of the field before any pattern is installed. The operating system underneath the operating system. What remains when all patterns are cleared."},{"t":"Superego","d":"The protective structure of the superficial mind. The story impressions handed down from an adult. The ego is more sophisticated because the ego is somatic in nature. The superego is superficial structure protecting beliefs."},{"t":"Tag","d":"The moment a charged experience is named and coded at a node address. The name locks the experience in. The tag is what the body scans for in all future input, firing the resident pattern when it finds a match."},{"t":"Two mechanics","d":"The two operations required for a complete release: (1) Release--the charge at the address reduces; (2) Embodied Truth--the replacement state is installed while the address is open. Both are required in sequence. The first without the second leaves no alternative at the address."},{"t":"Vritti","d":"A sensory input waveform and emotional input waveform. It channels across the nervous system, from the external field through the nervous system into the brain, where it's composited and perceived, and where awareness uses the sensory input to perceive. Once identified, the vritti is what collapses the nerve, the chakra, and the field of awareness."},{"t":"Willpower","d":"Available directed force. A measurement, not a character trait. It runs as a battery with a daily charge; sleep sets the starting level and moving through resistance spends it. High drag means low willpower. Release the charges, drag reduces, willpower rises. Not a separate instrument: will is directed intention, and any drag on it reads as resistance, which is already measured."}];
